(function(){
'use strict';
const K=window.Kingdom,I=window.KingdomInteract,LEVELS=20,app=document.getElementById('app');
const storage={getItem:k=>window.localStorage.getItem(k),setItem:(k,v)=>window.localStorage.setItem(k,v)};
const effectPrefs=I.preferences(storage),effects=I.createEffects(window,document,effectPrefs);
let dragApi=null,buildModel=I.newBuild(1),buildPicked=null;
const loaded=K.load(storage);let state=loaded.state,screen='home',level=1,number=1,selected=new Set(),answered=false,answeredCorrect=false,earned=0,audio=null,installEvent=null,offlineReady=false,trustedWorkers=new Set(),offlineRegistration=null,lastOfflineError=null,offlineBusy=false,toastTimer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(text){const el=document.getElementById('notice');el.textContent=text;el.hidden=!text;}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200);}
function persist(){const ok=K.save(storage,state);if(!ok)notice('التخزين غير متاح أو ممتلئ. قد يضيع التقدم عند الإغلاق. صدّر نسخة من لوحة التقدم.');return ok;}
if(loaded.error)notice(loaded.error);
const stars=n=>'★'.repeat(n)+'☆'.repeat(3-n);
const done=()=>Object.keys(state.completed).length;
const totalStars=()=>Object.values(state.completed).reduce((sum,c)=>sum+c.stars,0);
const nextLevel=()=>Math.min(LEVELS,done()+1);
const range=l=>{const ns=K.numbers(l);return `${K.ar(ns[0])} إلى ${K.ar(ns[4])}`;};
function statCards(){return `<div class="stats-strip"><div class="stat"><div class="stat-icon">⭐</div><div><strong>${K.ar(totalStars())}</strong><small>نجمة جمعتها</small></div></div><div class="stat"><div class="stat-icon">⚑</div><div><strong>${K.ar(done())} <span class="muted">/ ${K.ar(LEVELS)}</span></strong><small>مستوى اكتمل</small></div></div><div class="stat"><div class="stat-icon">✦</div><div><strong>${K.ar(done()*5)}</strong><small>عددًا تعلّمته</small></div></div></div>`;}
function home(){const next=nextLevel();return `<section class="hero"><div><div class="eyebrow">أهلًا ${state.name?esc(state.name):'يا بطل'}، مملكتك بانتظارك ✦</div><h1>كل عدد…<br><span>مغامرة جديدة!</span></h1><p>عدّ الفواكه، كوّن العشرات، والعب مع «حكيم» لتكتشف الأعداد من ١ إلى ١٠٠.</p><div class="hero-actions"><button class="btn" data-act="study" data-level="${next}">${done()?'أكمل مغامرتي':'لنبدأ المغامرة'} <span aria-hidden="true">←</span></button><a href="#guide" class="btn secondary">دليل الأهل</a></div></div><div class="hero-art" aria-hidden="true"><div class="art-ring"></div><span class="float-number n1">١</span><span class="float-number n2">٢</span><span class="float-number n3">٣</span><span class="spark s1">✦</span><span class="spark s2">✧</span><img src="./mascot.svg" width="200" height="225" alt=""><span class="hero-caption">حكيم، صديق رحلتك</span></div></section>${statCards()}${state.session?`<div class="review-banner">لديك لعبة لم تكتمل في المستوى ${K.ar(state.session.level)}. <button class="text-btn" data-act="resume">أكمل من حيث توقفت ←</button></div>`:''}<div class="section-top"><div><h2>خريطة المغامرة</h2><p>خمسة أعداد في كل محطة… وخطوة أقرب إلى المائة!</p></div><span class="label">${K.ar(LEVELS)} محطة سحرية</span></div><div class="journey-layout"><section class="level-grid" aria-label="مستويات التعلم">${Array.from({length:LEVELS},(_,i)=>{const l=i+1,c=state.completed[l],locked=!K.unlocked(state,l),current=l===next&&!c;return `<button class="level-card ${current?'current':''}" ${locked?'disabled':''} data-act="study" data-level="${l}" aria-label="المستوى ${K.ar(l)}، الأعداد ${range(l)}، ${locked?'مغلق':c?'مكتمل':'متاح'}"><span class="level-top"><span class="level-symbol" aria-hidden="true">${locked?'♧':c?'✓':l%4===0?'✦':['🌱','🍎','🌼','🌈'][(l-1)%4]}</span><small>${locked?'مغلق':c?'أحسنت!':'ابدأ هنا'}</small></span><strong>المستوى ${K.ar(l)}</strong><span class="level-range">${range(l)}</span><div class="level-stars" aria-label="${c?K.ar(c.stars):'٠'} من ٣ نجوم">${stars(c?.stars||0)}</div></button>`;}).join('')}</section><aside class="side-column"><div class="side-card"><img src="./mascot.svg" width="82" height="90" alt="حكيم البومة"><h3>${done()===LEVELS?'يا بطل المائة!':'مغامرتك التالية'}</h3><p>${done()===LEVELS?'أكملت المملكة! عد إلى أي مستوى لتحسين نجومك.':`هيا نكتشف الأعداد ${range(next)}، ثم نلعب معًا!`}</p><div class="number-pills">${K.numbers(next).map(n=>`<span>${K.ar(n)}</span>`).join('')}</div><button class="btn small" data-act="study" data-level="${next}">${done()===LEVELS?'ألعب من جديد':'هيا نكتشفها'} ←</button></div><div class="tip-card"><img src="./star.svg" class="star-friend" width="44" height="44" alt="لمعة، صديقة حكيم"><strong>قليل كل يوم، كثير مع الوقت</strong><p>جلسة من ٥–١٠ دقائق، مع وقت للمس الفواكه والعد بصوت مسموع.</p></div></aside></div><div class="route-footer"><span>✦ مراجعة كل أربعة مستويات</span><span>✦ كل خطأ فرصة لنتعلم</span><span>✦ صوت يعمل دون إنترنت</span></div>`;}
function quantity(n,interactive=false){const g=K.groups(n);let index=0;return `<div class="frames ${n>20?'quantity-compact':''}" ${interactive?'':'role="img"'} aria-label="${K.ar(n)} ثمرة تفاح، ${K.ar(g.tens)} عشرات و${K.ar(g.ones)} آحاد">${g.frames.map(count=>`<div class="ten-frame ${count===10?'complete':''}" data-count="${count}">${Array.from({length:10},(_,i)=>{if(i>=count)return '<span class="empty-slot" aria-hidden="true"></span>';index++;return interactive?`<button class="fruit" data-fruit="${index}" aria-label="تفاحة ${K.ar(index)}" aria-pressed="false">🍎</button>`:'<span class="fruit" aria-hidden="true">🍎</span>';}).join('')}</div>`).join('')}</div>`;}
function effectToolbar(){return `<div class="effect-toolbar" aria-label="خيارات المؤثرات"><button class="text-btn" data-act="effect-sound" data-effect-toggle="sound" aria-pressed="${effectPrefs.sound}">♫ المؤثرات الصوتية: ${effectPrefs.sound?'مفعّلة':'مكتومة'}</button><button class="text-btn" data-act="effect-motion" data-effect-toggle="motion" aria-pressed="${effectPrefs.motion}">✦ الحركة: ${effectPrefs.motion?'مفعّلة':'متوقفة'}</button></div>`;}
function builderContent(){const m=buildModel,g=K.groups(m.total),complete=m.total===m.target;
 return `<div class="section-top"><div><h3>🧺 كوّن العدد ${K.ar(m.target)} بالسحب</h3><p>تفاحة واحدة للآحاد، ومجموعة ١٠ للعشرات.</p></div><span class="label">${K.ar(m.total)} من ${K.ar(m.target)}</span></div><div class="build-palette"><button class="build-piece ${buildPicked===1?'picked':''}" data-act="pick-build" data-value="1" data-drag-kind="build" data-drag-value="1" data-drag-context="${m.target}" aria-pressed="${buildPicked===1}"><span aria-hidden="true">🍎</span><small>آحاد • ١</small></button>${m.target>=10?`<button class="build-piece ten-piece ${buildPicked===10?'picked':''}" data-act="pick-build" data-value="10" data-drag-kind="build" data-drag-value="10" data-drag-context="${m.target}" aria-pressed="${buildPicked===10}"><span class="ten-piece-grid" aria-hidden="true">${'<span>🍎</span>'.repeat(10)}</span><small>عشرة واحدة • ١٠</small></button>`:''}</div><div class="builder-houses" dir="ltr"><button class="build-house tens-house" dir="rtl" data-drop-target="build-tens" data-act="drop-build" data-zone="tens"><strong>بيت العشرات</strong><b>${K.ar(g.tens)}</b><small>اسحب مجموعة ١٠ هنا</small></button><button class="build-house ones-house" dir="rtl" data-drop-target="build-ones" data-act="drop-build" data-zone="ones"><strong>بيت الآحاد</strong><b>${K.ar(g.ones)}</b><small>اسحب تفاحة واحدة هنا</small></button></div><div class="build-quantity">${m.total?quantity(m.total):'<p class="helper">سلتك فارغة. هيا نكوّن العدد!</p>'}</div><p id="build-status" class="build-status" role="status">${complete?'أحسنت! كوّنت العدد '+K.ar(m.target)+' تمامًا ✓':'اسحب قطعة إلى بيتها، أو اضغط القطعة ثم البيت.'}</p><div class="actions"><button class="btn secondary small" data-act="undo-build" ${m.history.length?'':'disabled'}>أرجع آخر قطعة ↶</button><button class="btn secondary small" data-act="reset-build">نكوّن العدد من جديد</button></div>`;
}
function refreshBuilder(){const element=document.getElementById('builder');if(element)element.innerHTML=builderContent();}
function addBuild(value,zone){
 if(screen!=='study'||buildModel.target!==number)return;
 const result=I.placeBuild(buildModel,value,zone);
 if(!result.accepted){const text=result.reason==='zone'?'لنضع التفاحة الواحدة في بيت الآحاد، ومجموعة العشرة في بيت العشرات.':'هذه القطعة تزيد عن العدد المطلوب. جرّب قطعة أخرى أو أرجع آخر قطعة.';document.getElementById('build-status').textContent=text;effects.run('retry',document.getElementById('builder'));return;}
 buildPicked=null;refreshBuilder();
 if(result.grouped)document.getElementById('build-status').textContent=result.complete?'أحسنت! ١٠ آحاد كوّنت عشرة واحدة، وأكملت العدد '+K.ar(buildModel.target)+' ✓':'جميل! ١٠ آحاد كوّنت عشرة واحدة، فانتقلت إلى بيت العشرات.';
 effects.run(result.complete?'complete':'pick',document.getElementById('builder'));
}
function questionContext(){const s=state.session;return s?`${s.seed}:${s.phase}:${s.index}`:'';}
function receiveDrop(payload,target){
 if(payload.kind==='build'&&payload.context===String(number)&&['build-tens','build-ones'].includes(target))addBuild(payload.value,target==='build-tens'?'tens':'ones');
 if(payload.kind==='answer'&&target==='answer'&&screen==='quiz'&&payload.context===questionContext())giveAnswer(payload.value);
}
function toggleEffect(key){effectPrefs[key]=!effectPrefs[key];I.savePreferences(storage,effectPrefs);app.querySelectorAll('[data-effect-toggle]').forEach(button=>{const name=button.dataset.effectToggle;button.textContent=name==='sound'?`♫ المؤثرات الصوتية: ${effectPrefs.sound?'مفعّلة':'مكتومة'}`:`✦ الحركة: ${effectPrefs.motion?'مفعّلة':'متوقفة'}`;button.setAttribute('aria-pressed',String(effectPrefs[name]));});if(effectPrefs[key])effects.run('pick');}
function sheepGarden(n){
 if(!Number.isInteger(n)||n<1||n>100)return '';
 let sheep=0;return `<section class="sheep-garden" role="img" aria-label="حديقة فيها ${K.ar(n)} رأسًا من الأغنام"><div class="farm-scenery" aria-hidden="true"><img src="./farm-scene.svg" width="800" height="230" alt=""><span class="farm-sign">حديقة الأغنام</span></div><div class="garden-paddocks">${K.groups(n).frames.map(count=>`<div class="sheep-paddock" data-sheep-count="${count}">${Array.from({length:10},(_,i)=>i<count?`<img class="garden-sheep" src="./sheep.svg" width="36" height="30" alt="" data-sheep="${++sheep}">`:'<span class="sheep-empty" aria-hidden="true"></span>').join('')}</div>`).join('')}</div><p class="garden-hint">كل حظيرة ممتلئة فيها ١٠ أغنام. عدّها ثم اسحب العدد الصحيح.</p></section>`;
}
function study(){const ns=K.numbers(level);const seen=state.seen[level]||[];const g=K.groups(number);return `<div class="study-shell"><div class="page-heading"><div><div class="eyebrow">محطة الاكتشاف • الأعداد ${range(level)}</div><h1>المستوى ${K.ar(level)}: تعلّم والعب</h1></div><a class="btn secondary small" href="#home">الخريطة</a></div>${effectToolbar()}<div class="study-tabs" aria-label="الأعداد الخمسة">${ns.map(n=>`<button class="number-tab ${number===n?'active':''} ${seen.includes(n)?'viewed':''}" data-act="number" data-number="${n}" aria-label="${K.word(n)}${seen.includes(n)?'، شاهدته':''}" aria-pressed="${number===n}">${K.ar(n)}</button>`).join('')}</div><section class="study-card"><div class="study-intro"><div class="big-number">${K.ar(number)}</div><div><div class="study-word">${K.word(number)}</div><button class="audio-btn" data-act="audio" data-number="${number}">♫ استمع إلى العدد</button><div id="audio-error" class="audio-error" role="status"></div></div></div><div class="amount-area"><div class="amount-label"><strong>🍎 المس كل تفاحة، وعدّ معي</strong><button class="text-btn" data-act="reset-count">نعدّ من جديد ↺</button></div>${quantity(number,true)}<p id="count-status" class="count-status" role="status">لم نعدّ بعد. ابدأ بتفاحة!</p></div><div class="place-row" dir="ltr" aria-label="العشرات على اليسار والآحاد على اليمين"><div class="place-box" dir="rtl"><b>${K.ar(g.tens)}</b><span>عشرات</span></div><div class="place-box" dir="rtl"><b>${K.ar(g.ones)}</b><span>آحاد</span></div></div><p class="helper">كل إطار ممتلئ = ١٠ تفاحات = عشرة واحدة.${g.ones===0?' ٠ آحاد تعني: لا تفاحات متبقية خارج العشرات.':''}${number===100?' و١٠ عشرات = مائة واحدة.':''}</p><div class="equation" aria-label="${K.ar(number)} يساوي ${K.ar(g.tens*10)} زائد ${K.ar(g.ones)}">${K.ar(g.tens*10)} + ${K.ar(g.ones)} = ${K.ar(number)}</div><section id="builder" class="builder" aria-label="تكوين العدد بالسحب والإفلات">${builderContent()}</section><details class="writing"><summary>✎ أجرّب كتابة العدد بإصبعي</summary><p class="helper">تتبّع الرقم الفاتح. هذا تدريب حرّ؛ اطلب من شخص كبير مساعدتك.</p><div class="trace-wrap"><span class="trace-guide">${K.ar(number)}</span><canvas id="trace" aria-label="مساحة كتابة العدد ${K.ar(number)} بإصبعك أو بالقلم"></canvas></div><div class="actions"><button class="btn secondary small" data-act="clear-trace">امسح وأحاول ثانية</button></div></details></section><div class="actions">${number>ns[0]?'<button class="btn secondary" data-act="previous-number">العدد السابق</button>':''}${number<ns[4]?'<button class="btn" data-act="next-number">العدد التالي ←</button>':`<button class="btn" data-act="start-quiz" ${seen.length<5?'disabled':''}>أنا مستعد للعب! ←</button>`}</div><p class="helper">اكتشفت ${K.ar(seen.length)} من ٥ أعداد. شاهد البطاقات الخمس قبل اللعب.</p></div>`;}
function title(q){switch(q.kind){case'count':return 'كم تفاحة ترى؟ اسحب العدد الصحيح.';case'sheep':return 'كم خروفًا في الحديقة؟ اسحب العدد الصحيح.';case'sequence':return 'ما العدد الناقص؟ من الأصغر إلى الأكبر.';case'descending':return 'ما العدد الناقص؟ من الأكبر إلى الأصغر.';case'before':return `ما العدد الذي يأتي قبل ${K.ar(q.n)}؟`;case'after':return `ما العدد الذي يأتي بعد ${K.ar(q.n)}؟`;case'compare':return 'ابدأ من اليمين: العدد الأول… بالنسبة إلى الثاني؟';case'place':return 'عدّ العشرات والآحاد. ما عدد الآحاد؟';case'tens':return 'عدّ العشرات والآحاد. ما عدد العشرات؟';}}
const kindLabel=q=>({count:'حديقة الفواكه',sheep:'حديقة الأغنام',sequence:'قطار الأعداد',descending:'القطار العائد',before:'جار العدد',after:'جار العدد',compare:'ميزان الأعداد',place:'بيت الآحاد',tens:'بيت العشرات'})[q.kind];
function hasInlineTarget(q){return ['compare','sequence','descending','before','after','place','tens'].includes(q.kind);}
function numberTiles(values,missing,explain=false){return `<div class="sequence" dir="rtl" aria-label="اقرأ الأعداد من اليمين إلى اليسار">${values.map((v,i)=>`<span class="seq-num ${i===missing?'missing':''}" ${i===missing&&!explain?'data-drop-target="answer" aria-label="الخانة الفارغة: اسحب الإجابة هنا"':''}>${i===missing&&!explain?'؟':K.ar(v)}</span>`).join('')}</div><p class="helper">ابدأ من اليمين، واسحب الإجابة إلى خانة «؟».</p>`;}
function visual(q,explain=false){
 if(q.kind==='sheep')return sheepGarden(q.n);
 if(q.kind==='count')return `<div class="amount-area">${quantity(q.n)}</div>`;
 if(q.kind==='place'||q.kind==='tens'){
  const g=K.groups(q.n),asked=q.kind==='tens'?'tens':'ones';
  return `<div class="amount-area">${quantity(q.n)}<p class="helper">كل إطار كامل عشرة واحدة؛ التفاحات المتبقية آحاد.${q.n===100?' ١٠ عشرات تكوّن مائة.':''}</p></div><div class="place-row quiz-place" dir="ltr" aria-label="العشرات على اليسار والآحاد على اليمين">${[['tens','عشرات'],['ones','آحاد']].map(([part,label])=>`<div class="place-box ${part===asked?'missing':''}" dir="rtl" ${part===asked&&!explain?'data-drop-target="answer" aria-label="اسحب عدد '+label+' هنا"':''}><b data-answer-value>${part===asked&&!explain?'؟':K.ar(g[part])}</b><span>${label}</span></div>`).join('')}</div>`;
 }
 if(q.kind==='compare')return `<div class="comparison" dir="rtl"><div class="compare-number"><small>العدد الأول</small><b>${K.ar(q.n)}</b></div><div class="answer-drop compare-drop" data-drop-target="answer" aria-label="مكان رمز المقارنة">؟</div><div class="compare-number"><small>العدد الثاني</small><b>${K.ar(q.other)}</b></div></div><p class="helper comparison-help">نقرأ من اليمين. فتحة الرمز نحو العدد الأكبر، والطرف المدبّب نحو الأصغر.</p>`;
 if(q.kind==='sequence'||q.kind==='descending')return numberTiles(q.kind==='sequence'?[q.n-1,q.n,q.n+1]:[q.n+1,q.n,q.n-1],1,explain);
 if(q.kind==='before'||q.kind==='after')return numberTiles([q.n-1,q.n,q.n+1],q.kind==='before'?0:2,explain);
 return `<div class="big-number">${K.ar(q.n)}</div>`;
}
function choiceLabel(value){if(typeof value==='number')return K.ar(value);return `<span class="comparison-symbol" aria-hidden="true"><svg viewBox="0 0 64 64" width="56" height="56" focusable="false"><path d="${I.relationPath(value)}" fill="none" stroke="currentColor" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span class="comparison-caption">${value}</span>`;}
function quiz(){const s=state.session;if(!s)return home();const q=K.current(s);if(!q)return home();const total=s.phase==='quiz'?K.questions(s.level,s.seed).length:s.pending.length;return `<div class="study-shell"><div class="page-heading"><div><div class="eyebrow">المستوى ${K.ar(s.level)} • ${s.phase==='review'?'نراجع مع حكيم':'وقت اللعب'}</div><h1>${kindLabel(q)}</h1></div><a class="btn secondary small" href="#home">أحفظ وأستريح</a></div>${effectToolbar()}${s.phase==='review'?'<div class="review-banner">🌱 نعيد الأسئلة التي احتجنا فيها مساعدة. خذ وقتك، أنت تتعلم!</div>':q.review?'<div class="review-banner">✦ محطة مراجعة: سؤال من الأعداد التي تعلمتها سابقًا.</div>':''}<div class="question-card"><div class="question-top"><span class="question-kind">سؤال واحد، خطوة واحدة</span><small>السؤال ${K.ar(s.index+1)} من ${K.ar(total)}</small></div><div class="progress-track" role="progressbar" aria-valuenow="${s.index}" aria-valuemin="0" aria-valuemax="${total}" aria-label="تقدم الأسئلة"><progress value="${s.index}" max="${total}" aria-label="تقدم الأسئلة"></progress></div><h2 id="question-title">${title(q)}</h2><div class="question-visual">${visual(q)}</div>${!hasInlineTarget(q)?'<div class="answer-drop" data-drop-target="answer" aria-label="مكان الإجابة">اسحب الإجابة هنا ↓</div>':''}<p class="helper">اسحب الإجابة وأفلتها داخل المكان المحدد. الضغط وحده لا يختار إجابة.</p><div class="choices" role="list" aria-labelledby="question-title">${q.options.map((v,i)=>`<div class="choice ${typeof v==='string'?'word':''}" role="listitem" aria-label="اسحب ${typeof v==='number'?K.ar(v):v}" aria-disabled="false" data-drag-kind="answer" data-drag-value="${i}" data-drag-context="${questionContext()}">${choiceLabel(v)}</div>`).join('')}</div><div id="feedback" aria-live="polite" aria-atomic="true"></div><p class="helper">لا تستعجل. انظر، وعدّ، ثم اختر.</p></div></div>`;}
function explanation(q){const a=K.ar(q.answer);switch(q.kind){case'sheep':return `نعدّ الأغنام فنجد ${a}. كل حظيرة مكتملة فيها ١٠ أغنام.`;case'count':return `نعدّ التفاحات فنجد ${a}. كل إطار كامل فيه ١٠ تفاحات.`;case'before':return `نرجع خطوة واحدة: العدد قبل ${K.ar(q.n)} هو ${a}.`;case'after':return `نتقدم خطوة واحدة: العدد بعد ${K.ar(q.n)} هو ${a}.`;case'sequence':return `نقرأ من اليمين ونزيد واحدًا كل مرة: ${[q.n-1,q.n,q.n+1].map(K.ar).join('، ')}.`;case'descending':return `نقرأ من اليمين وننقص واحدًا كل مرة: ${[q.n+1,q.n,q.n-1].map(K.ar).join('، ')}.`;case'compare':return `${K.ar(q.n)} ${q.answer} ${K.ar(q.other)}. ${q.answer==='يساوي'?'الكميتان متساويتان.':'قارن العشرات أولًا، ثم الآحاد إذا تساوت العشرات.'}`;case'tens':return `${K.ar(q.n)} فيه ${a} عشرات و${K.ar(q.n%10)} آحاد. نعدّ الإطارات الكاملة؛ كل إطار عشرة واحدة.${q.n===100?' عشر عشرات تكوّن مائة.':''}`;case'place':return `${K.ar(q.n)} فيه ${K.ar(Math.floor(q.n/10))} عشرات و${a} آحاد. الآحاد هي ما يتبقى بعد تكوين العشرات.`;}}
function success(){return `<section class="success"><img src="./mascot.svg" width="125" height="135" alt="حكيم سعيد بإنجازك"><div class="success-stars" aria-label="${K.ar(earned)} نجوم">${stars(earned)}</div><h1>أحسنت ${state.name?esc(state.name):'يا بطل'}! 🎉</h1><p>أكملت المستوى ${K.ar(level)} وراجعت كل ما احتاج مساعدة.<br>${level===LEVELS?'وصلت إلى المائة… المملكة تحتفل بك!':'المحطة التالية بانتظارك.'}</p><div class="actions">${level<LEVELS?`<button class="btn" data-act="study" data-level="${level+1}">المستوى التالي ←</button>`:'<a class="btn" href="#progress">أشاهد إنجازي</a>'}<button class="btn secondary" data-act="certificate" data-level="${level}">شهادتي ✦</button><a class="btn secondary" href="#home">الخريطة</a></div><p class="helper">كل النجوم إنجاز جميل. يمكنك إعادة المستوى لتحسين نجومك.</p></section>`;}
function progress(){return `<div class="page-heading"><div><div class="eyebrow">كل خطوة تستحق الاحتفال</div><h1>لوحة تقدّمي</h1></div><a href="#home" class="btn secondary small">الخريطة</a></div>${statCards()}<section class="panel"><h2>بطل المملكة</h2><form id="name-form" class="profile-row"><label for="child-name">اسمي الأول:</label><input id="child-name" maxlength="40" autocomplete="off" value="${esc(state.name)}" placeholder="اكتب اسمًا أو لقبًا"><button class="btn small" type="submit">حفظ الاسم</button></form><p class="muted"><small>الاسم والتقدم محفوظان في هذا المتصفح على هذا الجهاز فقط.</small></p></section><section class="panel"><div class="section-top"><h2>محطاتي ونجومي</h2><span class="label">${K.ar(Math.round(done()/LEVELS*100))}٪ مكتمل</span></div><div class="progress-track"><progress value="${done()}" max="${LEVELS}" aria-label="تقدم المستويات"></progress></div>${done()?`<div class="progress-levels">${Object.entries(state.completed).map(([l,c])=>`<div class="progress-item"><strong>المستوى ${K.ar(l)}</strong><span aria-label="${K.ar(c.stars)} نجوم">${stars(c.stars)}</span><small>${range(+l)}</small><br><button class="text-btn" data-act="certificate" data-level="${l}">شهادة الإنجاز</button></div>`).join('')}</div>`:'<p class="empty-state">أول نجمة تنتظرك! ابدأ المستوى الأول 🌱</p>'}</section><section class="panel no-print"><h3>احتفظ بمغامرتك</h3><p class="muted">صدّر نسخة صغيرة قبل تغيير الجهاز أو مسح بيانات المتصفح.</p><div class="actions"><button class="btn secondary" data-act="export">تصدير التقدم ↓</button><label class="btn secondary" for="import-file" tabindex="0" role="button">استعادة نسخة ↑</label><input id="import-file" type="file" accept="application/json,.json" hidden></div><p id="backup-message" role="status" class="helper"></p></section>`;}
function certificate(l){const c=state.completed[l];if(!c)return progress();const all=done()===LEVELS&&l===LEVELS;const date=c.date?new Date(c.date).toLocaleDateString('ar'):'—';return `<div class="page-heading no-print"><a href="#progress" class="btn secondary">العودة إلى تقدّمي</a><button class="btn" data-act="print">طباعة الشهادة</button></div><section class="certificate"><div class="eyebrow">مملكة الأعداد السحرية</div><div class="medal">🏅</div><h2>${all?'شهادة بطل المائة':'شهادة إنجاز'}</h2><p>بكل حب وفخر، نحتفل بإنجاز</p><div class="name">${esc(state.name||'بطل المملكة')}</div><p>${all?'أكمل رحلة الأعداد من ١ إلى ١٠٠':`أكمل المستوى ${K.ar(l)} وتعلّم الأعداد ${range(l)}`}</p><p>وأنهى الألعاب ومراجعة الأخطاء بنجاح.</p><div class="success-stars" aria-label="${K.ar(c.stars)} نجوم">${stars(c.stars)}</div><p>«أتعلم، أحاول، وأنجح»</p><small class="muted">${date} • حكيم وأصدقاء المملكة</small></section><p class="helper no-print">يمكن حفظ الشهادة PDF من نافذة الطباعة. الشهادة تشجيعية تعليمية.</p>`;}
function guide(){return `<div class="page-heading"><div><div class="eyebrow">رفقة بسيطة تصنع الفرق</div><h1>دليل الأهل</h1></div><a href="#home" class="btn secondary small">لنلعب</a></div><div class="guide-grid"><section class="panel"><h2>كيف نتعلم؟</h2><p>كوّن الأعداد بسحب تفاحة إلى بيت الآحاد أو مجموعة عشرة إلى بيت العشرات. يمكنك أيضًا الضغط على القطعة ثم بيتها. وفي الاختبار تُختار الإجابة بالسحب والإفلات فقط؛ الضغط وحده لا يرسل إجابة. تشمل التمارين حديقة أغنام ملوّنة، في كل حظيرة ممتلئة عشرة أغنام.</p><ul><li>٢٠ مستوى، في كل مستوى خمسة أعداد جديدة.</li><li>شاهد البطاقات الخمس، واسمع العدد، والمس الفواكه مع الطفل.</li><li>كل إطار ممتلئ يمثّل عشرة؛ الباقي آحاد. الصفر يعني عدم وجود آحاد.</li><li>تدريب كتابة حر بالإصبع؛ يراجعه ولي الأمر، ولا يحكم التطبيق آليًا على الخط.</li><li>الألعاب تشمل العد والتسلسل الصاعد والنازل والمقارنة والسابق والتالي والعشرات والآحاد، بسؤال مستقل لكل منهما.</li><li>ثلاثة أسئلة مراجعة تراكمية كل أربعة مستويات.</li></ul></section><section class="panel"><h2>التصحيح والنجوم</h2><p>في المقارنة نبدأ بالعدد الأول على اليمين؛ فتحة الرمز نحو العدد الأكبر دائمًا. الرسوم ثابتة ولا تنعكس بتغير اتجاه النص. يمكن كتم المؤثرات وإيقاف الحركة من أزرار اللعب؛ الحركة تحترم إعداد تقليل الحركة في الجهاز. نطق الأعداد يبقى متاحًا بزر الاستماع.</p><p>خطأ؟ نوضح الفكرة بلطف ونمنح الطفل محاولة أخرى. ثم نعيد السؤال في مراجعة مستقلة في نهاية المستوى. لا يُفتح المستوى التالي حتى تُجاب جميع الأسئلة وأسئلة المراجعة بشكل صحيح.</p><p>٣ نجوم بلا أخطاء، نجمتان عند ١–٣ محاولات خاطئة، ونجمة عند أكثر من ذلك. إعادة المستوى تحتفظ بأفضل نتيجة.</p><p>مدة مقترحة: ٥–١٠ دقائق. امدح المحاولة والفهم، وخذ استراحة عند التعب.</p></section><section class="panel"><h2>حقيبة تعمل دون إنترنت</h2><p>اترك الصفحة مفتوحة أول مرة حتى تظهر عبارة «الحقيبة جاهزة دون إنترنت». يشمل التنزيل الأعداد المائة ونطقها المحلي. لا نعتمد على أصوات المتصفح.</p><p>بعدها جرّب وضع الطيران وأعد فتح الرابط أو التطبيق المثبّت. إذا مسح النظام بيانات الموقع، يلزم تنزيلها مجددًا.</p><div class="actions"><button class="btn small" data-act="install">تثبيت التطبيق</button><button class="btn secondary small" data-act="retry-offline">فحص الحقيبة</button></div><p class="helper">يمكن أيضًا اختيار «إضافة إلى الشاشة الرئيسية» من قائمة المتصفح. يلزم HTTPS، أو localhost عند التشغيل على الكمبيوتر.</p></section><section class="panel"><h2>التقدم والخصوصية</h2><p>ملف Magic-Numbers-Kingdom.zip نسخة من كود المشروع وأصواته وتعليمات تشغيله؛ ليس تطبيق Android ولا يحفظ تقدم الطفل بمجرد تنزيله.</p><p>الدروس والصوت للعمل دون إنترنت تُحفظ داخل تخزين Chrome الخاص بهذا الموقع، ويُحفظ الاسم والنجوم والمستويات في التخزين المحلي للموقع. ليست في ملف ZIP، ولا تتزامن تلقائيًا بين الأجهزة.</p><p>لا توجد إعلانات أو تحليلات أو حساب طفل. يُحفظ الاسم الأول والتقدم محليًا، ولا ينتقلان بين الأجهزة تلقائيًا. تصدير النسخة من لوحة التقدم يحمي إنجاز الطفل.</p><p>إذا تعذر التخزين سيظهر تنبيه؛ لا تعتمد على حفظ التقدم داخل التصفح الخاص.</p><p>النطق آلي عربي محفوظ بملفات MP3. يمكن استبدال أي ملف بتسجيل معلّم يحمل الاسم نفسه.</p><a class="btn secondary small" href="#progress">إدارة التقدم والنسخ الاحتياطي</a></section></div>`;}
function render(focus=false){if(dragApi)dragApi.cancel();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===screen));app.innerHTML=screen==='study'?study():screen==='quiz'?quiz():screen==='success'?success():screen==='progress'?progress():screen==='guide'?guide():screen==='certificate'?certificate(level):home();if(screen==='study')setupCanvas();if(focus){app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function markScreen(){history.replaceState(null,'','#'+screen);}
function route(){const hash=location.hash.slice(1);screen=['home','progress','guide'].includes(hash)?hash:'home';markScreen();stopAudio();render(true);}
function stopAudio(){if(audio){audio.onerror=null;audio.onended=null;audio.pause();audio=null;}}
function play(n){if(!Number.isInteger(n)||n<1||n>100)return;stopAudio();audio=new Audio(new URL(`audio/${n}.mp3`,document.baseURI).href);audio.preload='none';audio.onended=()=>{audio=null;};const fail=()=>{const el=document.getElementById('audio-error');if(el)el.textContent='تعذّر تشغيل الصوت. انتظر اكتمال تنزيل الحقيبة ثم اضغط للاستماع مرة أخرى.';else toast('تعذّر تشغيل الصوت. تحقق من اكتمال تنزيل الحقيبة.');};audio.onerror=fail;const p=audio.play();if(p)p.catch(fail);}
function setNumber(n,withAudio=true){if(!K.numbers(level).includes(n))return;number=n;buildModel=I.newBuild(n);buildPicked=null;selected=new Set();const seen=state.seen[level]||[];if(!seen.includes(n)){seen.push(n);state.seen[level]=seen;persist();}render();if(withAudio)play(n);}
function openStudy(l){if(!Number.isInteger(l)||l<1||l>LEVELS||!K.unlocked(state,l))return;stopAudio();screen='study';markScreen();level=l;setNumber(K.numbers(l)[0],false);app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function startQuiz(){if((state.seen[level]||[]).length!==5)return toast('شاهد البطاقات الخمس أولًا.');if(!state.session||state.session.level!==level)state.session=K.createSession(level,Date.now()>>>0);persist();screen='quiz';markScreen();answered=false;answeredCorrect=false;stopAudio();render(true);}
function giveAnswer(index){if(answered||!state.session)return;const q=K.current(state.session);if(!q||!Number.isInteger(index)||index<0||index>=q.options.length)return;answered=true;const value=q.options[index];const r=K.answer(state.session,value);answeredCorrect=r.correct;persist();const buttons=app.querySelectorAll('[data-drag-kind="answer"]');buttons.forEach((b,i)=>{b.dataset.dragDisabled='true';b.setAttribute('aria-disabled','true');if(i===index)b.classList.add(r.correct?'correct':'wrong');});app.querySelectorAll('[data-drop-target="answer"]').forEach(zone=>{(zone.querySelector('[data-answer-value]')||zone).innerHTML=choiceLabel(value);zone.classList.add(r.correct?'drop-correct':'drop-wrong');});const feedback=document.getElementById('feedback');feedback.className='feedback '+(r.correct?'':'wrong');feedback.innerHTML=`<p><strong>${r.correct?'أحسنت، اكتشاف رائع! ✦':'محاولة جميلة! لنفكر معًا 🌱'}</strong><br>${explanation(q)}</p>${!r.correct&&(q.kind==='compare')?`<div class="frames">${quantity(q.n)}<span class="muted">و</span>${quantity(q.other)}</div>`:''}<button class="btn small" data-act="${r.correct?'advance':'retry-answer'}">${r.correct?'نكمل ←':'أحاول مرة أخرى'}</button>`;effects.run(r.correct?'correct':'retry',feedback);}
function advance(){if(!answered||!answeredCorrect||!state.session)return;const result=K.advance(state.session);answered=false;if(result==='done'){level=state.session.level;earned=K.finish(state,state.session);screen='success';markScreen();}persist();render(true);if(result==='done')effects.run('complete',app.querySelector('.success'));}
app.addEventListener('click',async e=>{const fruit=e.target.closest('[data-fruit]');if(fruit){const i=+fruit.dataset.fruit;if(!selected.has(i)){selected.add(i);fruit.classList.add('counted');fruit.setAttribute('aria-pressed','true');const count=selected.size;document.getElementById('count-status').textContent=count===number?`أحسنت! عددنا ${K.ar(number)} تفاحة. جميعها محسوبة ✓`:`عددنا ${K.ar(count)}. لنعدّ التفاحة التالية.`;play(count);}return;}const button=e.target.closest('[data-act]');if(!button||button.disabled)return;switch(button.dataset.act){case'effect-sound':toggleEffect('sound');break;case'effect-motion':toggleEffect('motion');break;case'pick-build':if(screen==='study'){buildPicked=+button.dataset.value;refreshBuilder();effects.run('pick');}break;case'drop-build':if(buildPicked)addBuild(buildPicked,button.dataset.zone);else document.getElementById('build-status').textContent='اختر التفاحة أو مجموعة العشرة أولًا.';break;case'undo-build':I.undoBuild(buildModel);refreshBuilder();break;case'reset-build':buildModel=I.newBuild(number);buildPicked=null;refreshBuilder();break;case'study':openStudy(+button.dataset.level);break;case'number':setNumber(+button.dataset.number);break;case'next-number':if(number<K.numbers(level)[4])setNumber(number+1);break;case'previous-number':if(number>K.numbers(level)[0])setNumber(number-1);break;case'audio':play(+button.dataset.number);break;case'reset-count':selected.clear();app.querySelectorAll('[data-fruit]').forEach(f=>{f.classList.remove('counted');f.setAttribute('aria-pressed','false');});document.getElementById('count-status').textContent='لنعدّ من البداية. المس تفاحة!';break;case'start-quiz':startQuiz();break;case'resume':if(state.session){screen='quiz';markScreen();answered=false;answeredCorrect=false;level=state.session.level;render(true);}break;case'retry-answer':answered=false;answeredCorrect=false;render();break;case'advance':advance();break;case'certificate':if(state.completed[button.dataset.level]){level=+button.dataset.level;screen='certificate';markScreen();render(true);}break;case'print':window.print();break;case'clear-trace':{const c=document.getElementById('trace');if(c)c.getContext('2d').clearRect(0,0,c.width,c.height);break;}case'export':exportProgress();break;case'install':if(installEvent){await installEvent.prompt();await installEvent.userChoice;installEvent=null;}else toast('من قائمة المتصفح اختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية».');break;case'retry-offline':registerOffline(true);break;}});
app.addEventListener('submit',e=>{if(e.target.id==='name-form'){e.preventDefault();state.name=K.cleanName(document.getElementById('child-name').value);persist();toast('حفظنا اسم بطل المملكة ✦');}});
app.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files[0];if(!file)return;try{if(file.size>K.MAX_PROGRESS_BYTES)throw Error();const text=await file.text();const imported=K.importProgress(text);if(!window.confirm('استبدال التقدم الحالي بالتقدم الموجود في هذه النسخة؟'))return;state=imported;persist();render();toast('استعدنا مغامرتك بنجاح.');}catch{toast('هذه النسخة غير صالحة. لم يتغير تقدمك.');}});
app.addEventListener('keydown',e=>{if(e.target.matches('label[for="import-file"]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();document.getElementById('import-file').click();}});
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='magic-numbers-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('جهزنا نسخة تقدمك للتنزيل.');}
function setupCanvas(){const canvas=document.getElementById('trace');if(!canvas)return;let context,drawing=false;function size(){const rect=canvas.getBoundingClientRect();if(!rect.width)return;const ratio=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);context=canvas.getContext('2d');context.scale(ratio,ratio);context.strokeStyle='#147f77';context.lineWidth=6;context.lineCap='round';context.lineJoin='round';}const details=canvas.closest('details');details.addEventListener('toggle',()=>{if(details.open&&!context)size();});canvas.addEventListener('pointerdown',e=>{if(!context)size();if(!context)return;drawing=true;canvas.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect();context.beginPath();context.moveTo(e.clientX-r.left,e.clientY-r.top);});canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const r=canvas.getBoundingClientRect();context.lineTo(e.clientX-r.left,e.clientY-r.top);context.stroke();});const end=()=>{drawing=false;};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
window.addEventListener('hashchange',route);
window.addEventListener('storage',e=>{if(e.key===K.KEY){const fresh=K.load(storage);if(!fresh.error){state=fresh.state;screen='home';answered=false;render();toast('تم تحديث التقدم من نافذة أخرى.');}}});
const APP_VERSION='magic-numbers-v1.5.0';
function offlineStatus(message){document.getElementById('offline-status').textContent=message;}
function showOfflineDetail(title,text,diagnostic='',retry=true){
 const panel=document.getElementById('offline-detail');panel.hidden=false;
 document.getElementById('offline-detail-title').textContent=title;
 document.getElementById('offline-detail-text').textContent=text;
 document.getElementById('offline-detail-diagnostic').textContent=diagnostic;
 const button=document.getElementById('offline-retry');
 button.hidden=!retry;button.dataset.offlineAction=retry==='reload'?'reload':'retry';
 button.textContent=retry==='reload'?'تطبيق التحديث ↻':'استكمال التنزيل ↻';
}
function offlineFailure(info={}){
 lastOfflineError=info;
 const explanations={AUTH_REQUIRED:'يلزم فتح الموقع وتسجيل الدخول بحساب مالك الموقع أولًا.',STORAGE_FULL:'مساحة تخزين الموقع ممتلئة أو محظورة. وفّر مساحة على الهاتف ثم أعد المحاولة؛ لا تمسح بيانات الموقع حتى تصدّر التقدم.',TIMEOUT:'الاتصال بطيء. اترك الصفحة مفتوحة ومتّصلة ثم استكمل الملفات الناقصة.',INVALID_CONTENT:'وصل ملف بصيغة غير متوقعة. افتح الرابط مباشرة داخل Chrome ثم استكمل التنزيل.',INCOMPLETE:'بعض الملفات لم تُحفظ بعد. سنستكمل الملفات الناقصة فقط.',NETWORK:'انقطع التنزيل. اتصل بالإنترنت واترك هذه الصفحة مفتوحة ثم استكمل الملفات الناقصة.',REGISTRATION:'لم يبدأ حفظ التطبيق. افتح رابط الموقع مباشرة داخل Chrome مع اتصال بالإنترنت.'};
 offlineStatus('الحقيبة غير مكتملة • استكمل التنزيل');
 showOfflineDetail('لنجهّز الحقيبة دون إنترنت',explanations[info.code]||explanations.NETWORK,[info.file?`الملف: ${info.file}`:'',info.code?`السبب: ${info.code}`:'',Number.isFinite(info.done)?`محفوظ: ${K.ar(info.done)} من ${K.ar(info.total||112)}`:''].filter(Boolean).join(' • '));
}
function checkWorker(worker){if(!worker)return;trustedWorkers.add(worker);worker.postMessage({type:'CHECK_READY'});}
async function registerOffline(force=false){
 if(!('serviceWorker' in navigator)){offlineStatus('الحفظ دون إنترنت غير متاح');return;}
 if(offlineBusy)return;
 offlineBusy=true;if(force)lastOfflineError=null;
 try{
  offlineStatus('جارٍ تجهيز الحقيبة…');
  if(force)showOfflineDetail('نستكمل التنزيل','اترك الصفحة مفتوحة حتى اكتمال الملفات. لن يتغير تقدم الطفل.','',false);
  const registration=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});offlineRegistration=registration;
  const watch=worker=>{
   if(!worker)return;trustedWorkers.add(worker);
   worker.addEventListener('statechange',()=>{
    if(worker.state==='activated')checkWorker(worker);
    if(worker.state==='redundant'&&!offlineReady&&!lastOfflineError)offlineFailure({code:'REGISTRATION'});
   });
  };
  watch(registration.installing);watch(registration.waiting);watch(registration.active);
  registration.addEventListener('updatefound',()=>watch(registration.installing));
  if(registration.active?.state==='activated')checkWorker(registration.active);
  // Explicit retry must run an update check, even after an earlier failed install.
  if(force)await registration.update();
 }catch(e){offlineFailure({code:e.name==='QuotaExceededError'?'STORAGE_FULL':'REGISTRATION'});}
 finally{offlineBusy=false;}
}
if('serviceWorker' in navigator){
 navigator.serviceWorker.addEventListener('message',e=>{
  if(!trustedWorkers.has(e.source))return;
  const data=e.data||{};
  if(data.type==='CACHE_PROGRESS'){
   offlineReady=false;lastOfflineError=null;
   offlineStatus(`تجهيز الحقيبة ${K.ar(data.percent)}٪`);
   showOfflineDetail('نحفظ الدروس والصوت على جهازك',`تم حفظ ${K.ar(data.done)} من ${K.ar(data.total)} ملفًا. أبقِ الصفحة مفتوحة ومتّصلة.`,'',false);
  }
  if(data.type==='OFFLINE_READY'){
   offlineReady=true;lastOfflineError=null;offlineStatus('الحقيبة جاهزة دون إنترنت ✓');
   document.getElementById('offline-detail').hidden=true;
   if(data.version&&data.version!==APP_VERSION)showOfflineDetail('التحديث جاهز','اضغط تطبيق التحديث لعرض أحدث التحسينات. تقدم الطفل محفوظ.','','reload');
  }
  if(data.type==='CACHE_ERROR')offlineFailure(data);
 });
 navigator.serviceWorker.addEventListener('controllerchange',()=>checkWorker(navigator.serviceWorker.controller));
}
document.getElementById('offline-retry').addEventListener('click',()=>{
 const button=document.getElementById('offline-retry');if(button.hidden)return;
 if(button.dataset.offlineAction==='reload'){if(!persist()){toast('تعذر حفظ التقدم. صدّر نسخة من لوحة التقدم قبل إعادة التحميل.');return;}stopAudio();window.location.reload();}
 else registerOffline(true);
});
window.addEventListener('online',()=>{if(!offlineReady)registerOffline(true);});
dragApi=I.attachDrag(app,{document,window,canStart:payload=>payload.kind==='answer'?(screen==='quiz'&&!answered):screen==='study',onDrop:receiveDrop});
route();registerOffline();
// Exposed pure rendering for DOM-free asset/quantity validation; no data mutation.
window.KingdomView={quantity,title,visual,explanation,choiceLabel,builderContent,receiveDrop,sheepGarden};
})();
